// Headless rules test: runs many all-AI games with a no-op presenter to catch
// logic bugs (stalls, negative cash, invalid ownership) without any rendering.
//   npm run simulate -- 200
import { createGame } from "../src/game/state.js";
import { GameEngine } from "../src/game/engine.js";
import { AIController } from "../src/game/controllers.js";
import { TILES } from "../src/game/board.js";

const N = +(process.argv[2] || 100);

const passthrough = {
  buyChoice: (c, a) => a, rentChoice: (c, a) => a, jailChoice: (c, a) => a,
  aiAction: (c, a) => a, tradeResponse: (c, a) => a, targetChoice: (c, a) => a,
  runDuel: ({ a, b }) => (Math.random() < 0.5 ? a.id : b.id),
  runAuction: ({ bidders, aiValues }) => {
    const bids = bidders.map((b) => ({ id: b.id, v: aiValues[b.id] ?? 0 })).sort((x, y) => y.v - x.v);
    if (!bids.length || bids[0].v <= 0) return null;
    const price = Math.max(10, Math.min(bids[0].v, (bids[1]?.v ?? 5) + 5));
    return { winner: bids[0].id, price };
  },
  runHeist: () => Math.floor(Math.random() * 4),
};
const stats = { games: 0, rounds: 0, duels: 0, bankrupt: 0, turns: 0, cards: {}, reasons: {} };

function makePresenter(state) {
  return new Proxy({}, {
    get(_, k) {
      if (k in passthrough) return async (...a) => passthrough[k](...a);
      if (k === 'syncPlayers') return () => check(state);
      if (k === 'bankrupt') return async () => {};
      if (k === 'showCard') return async (p, deck, card) => { stats.cards[card.id] = (stats.cards[card.id] || 0) + 1; };
      return async () => { check(state); };
    },
  });
}

function check(s) {
  for (const p of s.players) {
    if (!p.bankrupt && p.cash < 0) throw new Error(`negative cash ${p.name} ${p.cash}`);
    if (!Number.isFinite(p.cash)) throw new Error('NaN cash');
  }
  for (const [i, t] of Object.entries(s.tiles)) {
    if (t.owner !== null && s.players[t.owner].bankrupt) throw new Error(`bankrupt owner on ${TILES[i].name}`);
    if (t.level < 0 || t.level > 5) throw new Error('bad level');
    if (t.owner === null && t.level > 0) throw new Error('level on unowned');
  }
  if (s.vault < 0) throw new Error('negative vault');
}

for (let g = 0; g < N; g++) {
  const n = 2 + (g % 3);
  const levels = ['easy', 'normal', 'hard'];
  const state = createGame({
    players: Array.from({ length: n }, (_, i) => ({ charId: ['rex', 'tina', 'cap', 'pepper'][i], isAI: true, aiLevel: levels[(g + i) % 3] })),
    settings: { roundLimit: g % 4 === 0 ? 30 : 0 },
    seed: g + 1,
  });
  const P = makePresenter(state);
  const ctrls = state.players.map(() => new AIController(P));
  const engine = new GameEngine(state, { presenter: P, controllers: ctrls });
  const origDuel = engine.duel.bind(engine);
  engine.duel = async (...a) => { stats.duels++; return origDuel(...a); };
  const origTurn = engine.playTurn.bind(engine);
  engine.playTurn = async (p) => {
    stats.turns++;
    if (state.round > 400) throw new Error(`game ${g} stalled (round ${state.round})`);
    return origTurn(p);
  };
  await engine.run();
  check(state);
  stats.games++;
  stats.rounds += state.round;
  stats.bankrupt += state.players.filter((p) => p.bankrupt).length;
  stats.reasons[state.endReason] = (stats.reasons[state.endReason] || 0) + 1;
}

console.log(`games ${stats.games}  avg rounds ${(stats.rounds / stats.games).toFixed(1)}  avg turns ${(stats.turns / stats.games).toFixed(0)}`);
console.log(`avg duels ${(stats.duels / stats.games).toFixed(1)}  bankruptcies ${stats.bankrupt}  end reasons`, stats.reasons);
console.log('cards drawn', stats.cards);

